package net.officefloor.hq.app.person;

import java.sql.Date;
import java.util.List;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Stores a transfer of a person to another sheet (see #transfer). */
@Repository
public class PersonTransferrer {

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;
    private final PersonRepository people;

    public PersonTransferrer(JdbcTemplate jdbc, SheetRepository sheets, PersonRepository people) {
        this.jdbc = jdbc;
        this.sheets = sheets;
        this.people = people;
    }

    /**
     * Moves the person to the other sheet with their grades (and from-dates), terms, contact and aliases, added there on
     * its today at the end of its list; and their claims with their status, dates, notes, tags, frozen figures, logs, comments and reminders,
     * listed there as its newest claims in the order they were listed, each unbound from any statement figure, without its
     * reference, lock or settle batch. Their statements, holds, watchers, patron links (either way), pool memberships,
     * period totals and retirement log are dropped: they leave this sheet entirely. Returns the ids of the moved claims
     * that have a number, in the order they were opened (by the sheet's today when each was opened, then as added), for
     * the caller to number on the other sheet.
     */
    public List<Long> transfer(Person person, String to) {
        String from = person.sheetId();
        long id = person.id();
        List<Long> claims = jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY listed, id",
                Long.class, from, id);
        List<Long> numbered = jdbc.queryForList("SELECT c.id FROM claim c WHERE c.sheet_id = ? AND c.person_id = ?"
                + " AND c.claim_number IS NOT NULL ORDER BY (SELECT MIN(l.log_date) FROM claim_log l WHERE l.sheet_id = c.sheet_id"
                + " AND l.claim_id = c.id AND l.status = 'OPEN') NULLS LAST, c.id", Long.class, from, id);
        for (Long c : claims) {
            for (String table : List.of("claim_log", "claim_reminder", "claim_comment", "claim_void_reason")) {
                jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND claim_id = ?", to, from, c);
            }
            jdbc.update("UPDATE claim_edit SET sheet_id = ?, ref = NULL WHERE sheet_id = ? AND claim_id = ?", to, from, c);
            jdbc.update("DELETE FROM claim_batch WHERE sheet_id = ? AND claim_id = ?", from, c);
            jdbc.update("UPDATE claim SET sheet_id = ?, stated = FALSE, stated_due = NULL, ref = NULL, ref_key = NULL, locked_by = NULL, "
                    + "listed = (SELECT COALESCE(MAX(x.listed), 0) + 1 FROM claim x WHERE x.sheet_id = ?) WHERE id = ?",
                    to, to, c);
        }

        jdbc.update("DELETE FROM patron WHERE sheet_id = ? AND (person_id = ? OR patron_id = ?)", from, id, id);
        jdbc.update("DELETE FROM pool_member WHERE person_id = ?", id);
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND person_id = ?", from, id);
        for (String table : List.of("statement", "person_hold", "watch", "person_retire_log")) {
            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", from, id);
        }
        for (String table : List.of("person_grade", "person_grade_log", "person_terms_log", "person_alias")) {
            jdbc.update("UPDATE " + table + " SET sheet_id = ? WHERE sheet_id = ? AND person_id = ?", to, from, id);
        }
        jdbc.update("UPDATE person SET sheet_id = ?, added_on = ? WHERE sheet_id = ? AND id = ?", to,
                Date.valueOf(sheets.today(to)), from, id);
        people.toEnd(to, id);
        return numbered;
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.claim.ClaimNumbering;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Stores the transfer (see PersonTransferrer#transfer), then gives each moved claim that had a number the next number
 *  of the other sheet (see ClaimNumbering), in the order the claims were opened. */
public class TransferPerson {
    public void transfer(@Val PersonTransfer transfer, PersonTransferrer transferrer, ClaimRepository claims,
            PeriodRepository periods, SettingRepository settings, SheetRepository sheets) {
        String to = transfer.toSheet();
        for (long id : transferrer.transfer(transfer.person(), to)) {
            claims.renumber(claims.find(to, id), ClaimNumbering.next(claims.find(to, id), claims, periods, settings, sheets));
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes PERSON_TRANSFERRED name=<name> to=<sheet> on the sheet the person left, then that sheet's figures the transfer
 *  moved (see Rollup), then PERSON_TRANSFERRED name=<name> from=<sheet> on the sheet they went to, then that sheet's. */
public class RecordPersonTransferred {
    public void record(@Val PersonTransfer transfer, @Val RollupBefore before, Rollup rollup, Audit audit) {
        String from = transfer.person().sheetId();
        String to = transfer.toSheet();
        String name = transfer.person().name();
        audit.record("PERSON_TRANSFERRED sheet=" + from + " by=" + transfer.by() + " name=" + name + " to=" + to);
        rollup.record(from, transfer.by(), before);
        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + transfer.by() + " name=" + name + " from=" + from);
        rollup.record(to, transfer.by(), transfer.toBefore());
    }
}

